func simdAMD128Float32GT(values []float32, validity, out memory.Bitmap, threshold float32) int {
	if len(values) < 4 {
		return scalarFloat32GT(values, validity, out, threshold)
	}
	words := prepareComparison(len(values), out)
	vectorThreshold := archsimd.BroadcastFloat32x4(threshold)
	selected := 0
	for wi := 0; wi < words; wi++ {
		base := wi * 64
		rows := min(64, len(values)-base)
		validWord := bitmapWord(validity, wi) & memory.TailMask(rows)
		// prepareComparison cleared every logical output word, including skipped words.
		if validWord == 0 {
			continue
		}
		var word uint64
		off := 0
		for ; off+4 <= rows; off += 4 {
			mask := archsimd.LoadFloat32x4(values[base+off:]).Greater(vectorThreshold)
			word |= uint64(mask.ToBits()) << uint(off)
		}
		for ; off < rows; off++ {
			if values[base+off] > threshold {
				word |= uint64(1) << uint(off)
			}
		}
		word &= validWord
		out[wi] = word
		selected += bits.OnesCount64(word)
	}
	return selected
}

